      font-weight: 700;
      color: #EB0028;
      letter-spacing: -0.5px;
    }

    .logo-idea {
      color: #121212;
    }

    .logo-forum {
      color: #121212;
    }

    .logo-e {
      display: inline-block;
      width: 22px;
      height: 22px;
      border: 2px dashed #CCCCCC;
      border-radius: 3px;
      margin: 0 1px;
      vertical-align: middle;
      position: relative;
    }

    .error-message {
      text-align: center;
      margin-bottom: 32px;
    }

    .error-message h1 {
      font-size: 24px;
      font-weight: 600;
      color: #121212;
      margin-bottom: 12px;
    }

    .error-message p {
      font-size: 16px;
      color: #444444;
      max-width: 400px;
    }

    .search-container {
      width: 100%;
      max-width: 440px;
      margin-bottom: 40px;
      position: relative;
    }

    .search-form {
      display: flex;
      align-items: center;
      border: 1px solid #CCCCCC;
      border-radius: 8px;
      overflow: hidden;
      background: #FFFFFF;
      transition: border-color 0.2s ease, box-shadow 0.2s ease;
    }

    .search-form:focus-within {
      border-color: #EB0028;
      box-shadow: 0 0 0 3px rgba(235, 0, 40, 0.1);
    }

    .search-input {
      flex: 1;
      padding: 14px 16px;
      font-size: 15px;
      font-family: inherit;
      border: none;
      outline: none;
      background: transparent;
      color: #121212;
    }

    .search-input::placeholder {
      color: #999999;
    }

    .search-button {
      padding: 14px 18px;
      background: transparent;
      border: none;
      cursor: pointer;
      color: #696969;
      transition: color 0.2s ease;
    }

    .search-button:hover {
      color: #EB0028;
    }

    .search-button svg {
      display: block;
      width: 20px;
      height: 20px;
    }

    .error-code-bar {
      width: 100%;
