      .logo-e {
        width: 26px;
        height: 26px;
      }

      .error-message h1 {
        font-size: 28px;
      }

      .cookie-content {
        flex-direction: row;
        align-items: center;
        justify-content: space-between;
      }

      .cookie-text {
        flex: 1;
      }

      .cookie-actions {
        flex-shrink: 0;
      }
    }
  </style>
