  <header class="logo">
    <span class="logo-text">
      <span class="logo-idea">Idea</span><span class="logo-e"></span><span class="logo-forum">Forum</span>
    </span>
  </header>

  <main>
    <section class="error-message">
      <h1>Sorry, we can't find that.</h1>
      <p>Perhaps we can help you find the content you're looking for:</p>
    </section>

    <section class="search-container">
      <form class="search-form" action="/search" method="get">
        <input
          type="search"
          name="q"
          class="search-input"
          placeholder="Search IdeaForum..."
          aria-label="Search"
        >
        <button type="submit" class="search-button" aria-label="Search">
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2">
            <circle cx="11" cy="11" r="8"/>
            <path d="m21 21-4.35-4.35"/>
          </svg>
        </button>
      </form>
    </section>

    <section class="error-code-bar">
      <span>HTTP Error 404</span>
    </section>

    <section class="next-steps">
      <h2>What's next?</h2>
      <nav class="nav-links">
        <a href="/homepage">Go to the homepage</a>
        <a href="/help-desk">Visit our Help Desk</a>
      </nav>
    </section>
  </main>

  <div class="cookie-banner" id="cookieBanner">
    <div class="cookie-content">
      <p class="cookie-text">
        This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics, personalization, and targeted advertising. To learn more, view the following link:
        <a href="/privacy-policy" target="_blank" rel="noopener">Privacy Policy</a>
      </p>
      <div class="cookie-actions">
        <button class="manage-preferences-btn" id="managePreferencesBtn">Manage Preferences</button>
      </div>
    </div>
  </div>

  <div class="modal-overlay" id="preferencesModal">
    <div class="modal-panel">
      <div class="modal-header">
        <h3>Cookie Preferences</h3>
        <button class="modal-close" id="closeModal" aria-label="Close">&times;</button>
      </div>
      <div class="modal-body">
        <div class="preference-section">
          <h4>Essential Cookies</h4>
          <p>These cookies are necessary for the website to function and cannot be switched off.</p>
          <div class="toggle-row">
            <span class="toggle-label">Required functionality</span>
            <label class="toggle-switch">
              <input type="checkbox" checked disabled>
              <span class="toggle-slider"></span>
            </label>
          </div>
        </div>

        <div class="preference-section">
          <h4>Analytics & Performance</h4>
          <p>Help us understand how visitors interact with our website.</p>
          <div class="toggle-row">
            <span class="toggle-label">Analytics cookies</span>
            <label class="toggle-switch">
              <input type="checkbox" id="analyticsToggle">
              <span class="toggle-slider"></span>
            </label>
          </div>
        </div>

        <div class="preference-section">
          <h4>Personalization & Advertising</h4>
          <p>Used to deliver personalized advertisements.</p>
          <div class="toggle-row">
            <span class="toggle-label">Advertising cookies</span>
            <label class="toggle-switch">
              <input type="checkbox" id="advertisingToggle">
              <span class="toggle-slider"></span>
            </label>
          </div>
          <div class="toggle-row">
            <span class="toggle-label">Personalization cookies</span>
            <label class="toggle-switch">
              <input type="checkbox" id="personalizationToggle">
              <span class="toggle-slider"></span>
            </label>
          </div>
        </div>
      </div>
      <div class="modal-footer">
        <button class="btn-secondary" id="cancelBtn">Cancel</button>
        <button class="btn-primary" id="saveBtn">Save Preferences</button>
      </div>
    </div>
  </div>

  <script>
    const manageBtn = document.getElementById('managePreferencesBtn');
    const modal = document.getElementById('preferencesModal');
    const closeBtn = document.getElementById('closeModal');
    const cancelBtn = document.getElementById('cancelBtn');
    const saveBtn = document.getElementById('saveBtn');

    function openModal() {
      modal.classList.add('active');
      document.body.style.overflow = 'hidden';
    }

    function closeModal() {
      modal.classList.remove('active');
      document.body.style.overflow = '';
    }

    manageBtn.addEventListener('click', openModal);
    closeBtn.addEventListener('click', closeModal);
    cancelBtn.addEventListener('click', closeModal);

    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeModal();
    });

    saveBtn.addEventListener('click', () => {
      closeModal();
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && modal.classList.contains('active')) {
        closeModal();
      }
    });
  </script>
</body>
